{
  "$schema": "https://schema.tauri.app/config/2",
  "productName": "MD Studio",
  "version": "0.1.1",
  "identifier": "dev.mdstudio.app",
  "build": {
    "beforeDevCommand": "pnpm dev",
    "devUrl": "http://localhost:1420",
    "beforeBuildCommand": "pnpm build",
    "frontendDist": "../dist"
  },
  "app": {
    "windows": [
      {
        "label": "main",
        "title": "MD Studio",
        "width": 1280,
        "height": 800,
        "resizable": true,
        "visible": false
      },
      {
        "label": "splashscreen",
        "title": "MD Studio",
        "url": "splashscreen.html",
        "width": 420,
        "height": 280,
        "resizable": false,
        "decorations": false,
        "center": true,
        "visible": true,
        "alwaysOnTop": true
      }
    ],
    "security": {
      "csp": "default-src 'self'; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; font-src 'self' data:; script-src 'self'; connect-src 'self' ipc: http://ipc.localhost"
    }
  },
  "bundle": {
    "active": true,
    "targets": [
      "deb",
      "appimage"
    ],
    "icon": [
      "icons/32x32.png",
      "icons/128x128.png",
      "icons/128x128@2x.png",
      "icons/icon.png",
      "icons/icon.ico"
    ],
    "fileAssociations": [
      {
        "ext": ["md"],
        "name": "Markdown",
        "description": "Markdown document",
        "mimeType": "text/markdown",
        "role": "Editor"
      },
      {
        "ext": ["markdown"],
        "name": "Markdown",
        "description": "Markdown document",
        "mimeType": "text/x-markdown",
        "role": "Editor"
      },
      {
        "ext": ["mdx"],
        "name": "MDX",
        "description": "MDX document",
        "mimeType": "text/mdx",
        "role": "Editor"
      }
    ],
    "linux": {
      "deb": {
        "desktopTemplate": "linux/md-studio.desktop"
      }
    }
  }
}
